// FILE: recent-transactions.component.ts
import { Component, Injectable, inject } from '@angular/core';

type Transaction = Readonly<{ id: string; label: string; amountMinor: number }>;

@Injectable({ providedIn: 'root' })
export class TransactionService {
  private readonly sample: readonly Transaction[] = [
    { id: 't1', label: 'Demo grocery purchase', amountMinor: -2599 },
    { id: 't2', label: 'Demo salary credit', amountMinor: 125000 }
  ];

  getRecent(): Transaction[] {
    return this.sample.map(transaction => ({ ...transaction }));
  }
}

@Component({
  selector: 'app-recent-transactions',
  standalone: true,
  template: `
    <h2>Recent fictional transactions</h2>
    <ul>
      @for (tx of transactions; track tx.id) {
        <li>{{ tx.label }}: {{ tx.amountMinor }} minor units</li>
      }
    </ul>
  `
})
export class RecentTransactionsComponent {
  private readonly transactionService = inject(TransactionService);
  readonly transactions = this.transactionService.getRecent();
}

