import { Component, Injectable, computed, inject, signal } from '@angular/core';

@Injectable({ providedIn: 'root' })
export class DisplayPreferencesService {
  private readonly highContrastState = signal(false);
  readonly highContrast = this.highContrastState.asReadonly();
  readonly mode = computed(() => this.highContrast() ? 'high' : 'normal');

  toggleContrast(): void {
    this.highContrastState.update(value => !value);
  }

  reset(): void {
    this.highContrastState.set(false);
  }
}

@Component({
  selector: 'app-workspace-preferences',
  standalone: true,
  template: `
    <button type="button" (click)="preferences.toggleContrast()">
      Toggle contrast
    </button>
    <output>Current mode: {{ preferences.mode() }}</output>
  `
})
export class WorkspacePreferencesComponent {
  readonly preferences = inject(DisplayPreferencesService);
}

