import { Component, Injectable, computed, inject, signal } from '@angular/core';

type DemoAccount = Readonly<{
  id: string;
  holder: string;
  currency: 'INR';
  balanceMinor: number;
}>;

@Injectable({ providedIn: 'root' })
export class AccountService {
  private readonly accountState = signal<DemoAccount>({
    id: 'demo-001', holder: 'Demo Customer', currency: 'INR', balanceMinor: 125000
  });
  readonly account = this.accountState.asReadonly();
  readonly balanceLabel = computed(() =>
    `${this.account().currency} ${(this.account().balanceMinor / 100).toFixed(2)}`
  );
  refreshFromDemoSnapshot(): void {
    this.accountState.set({ ...this.account(), balanceMinor: 127500 });
  }
}

@Component({
  selector: 'app-account-header', standalone: true,
  template: `<header>{{ accounts.account().holder }}
    <button type="button" (click)="accounts.refreshFromDemoSnapshot()">
      Refresh demo snapshot
    </button></header>`
})
export class AccountHeaderComponent {
  readonly accounts = inject(AccountService);
}

@Component({
  selector: 'app-account-balance-card', standalone: true,
  template: `<section aria-label="Demo balance">
    {{ accounts.balanceLabel() }}
  </section>`
})
export class AccountBalanceCardComponent {
  readonly accounts = inject(AccountService);
}

@Component({
  selector: 'app-shared-account-demo', standalone: true,
  imports: [AccountHeaderComponent, AccountBalanceCardComponent],
  template: `<app-account-header /><app-account-balance-card />`
})
export class SharedAccountDemoComponent {}
